var ASPN={conj:'соединение',sq:'квадрат',opp:'оппозиция',tri:'трин',sex:'секстиль'};
function aspX(a,b,orb){var d=Math.abs(rev(a-b+180)-180),L=[['conj',0],['sq',90],['tri',120],['opp',180]];for(var i=0;i<L.length;i++){var o=Math.abs(d-L[i][1]);if(o<=(L[i][0]==='sex'?orb*0.7:orb))return[L[i][0],o]}return null}
function windows(fn){var out=[],cur=null;for(var t=Date.UTC(2027,0,1);t<=Date.UTC(2027,11,31);t+=86400000){var v=fn(new Date(t));if(v){if(cur&&cur.key===v&&t-cur.e<=45*86400000){cur.e=t}else{cur={key:v,s:t,e:t};out.push(cur)}}}return out}
function rev(x){x%=360;return x<0?x+360:x}
function lonOf(b,d){if(b==='Moon')return rev(A.EclipticGeoMoon(d).lon);return rev(A.Ecliptic(A.GeoVector(A.Body[b],d,true)).elon)}
function meanNode(d){var T=(d.getTime()/86400000+2440587.5-2451545.0)/36525;return rev(125.04452-1934.136261*T)}
function sgn(l){return Math.floor(rev(l)/30)}
function tzOff(ms,zone){var f=new Intl.DateTimeFormat('en-US',{timeZone:zone,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});var p={};f.formatToParts(new Date(ms)).forEach(function(x){p[x.type]=x.value});return Date.UTC(+p.year,+p.month-1,+p.day,+p.hour%24,+p.minute,+p.second)-ms}
function localToUtc(y,m,d,h,mi,zone){var g=Date.UTC(y,m-1,d,h,mi);var u=g-tzOff(g,zone);return g-tzOff(u,zone)}
function ascLon(dt,lat,lon){var gst=A.SiderealTime(dt);var ramc=(gst*15+lon)*Math.PI/180,eps=23.4393*Math.PI/180,phi=lat*Math.PI/180;var a=Math.atan2(Math.cos(ramc),-(Math.sin(ramc)*Math.cos(eps)+Math.tan(phi)*Math.sin(eps)));return rev(a*180/Math.PI)}
function houseOfSign(start,s){return((s-start+12)%12)+1}
function oblq(d){var T=(d.getTime()/86400000+2440587.5-2451545)/36525;return (23.4392911-0.0130042*T)*Math.PI/180}
function topoLon(b,d,lat,lon){var eq=A.Equator(A.Body[b],d,new A.Observer(lat,lon,0),true,true),e=oblq(d),ra=eq.ra*15*Math.PI/180,de=eq.dec*Math.PI/180;return rev(Math.atan2(Math.sin(ra)*Math.cos(e)+Math.tan(de)*Math.sin(e),Math.cos(ra))*180/Math.PI)}
function placidus(d,lat,lon){var e=oblq(d),ramc=rev(A.SiderealTime(d)*15+lon),phi=lat*Math.PI/180;
 function l4ra(ra){ra*=Math.PI/180;return rev(Math.atan2(Math.sin(ra),Math.cos(ra)*Math.cos(e))*180/Math.PI)}
 var r=ramc*Math.PI/180,asc=rev(Math.atan2(Math.cos(r),-(Math.sin(r)*Math.cos(e)+Math.tan(phi)*Math.sin(e)))*180/Math.PI),mc=l4ra(ramc);
 if(Math.abs(lat)>62){var q=[];for(var i=0;i<12;i++)q.push(rev(asc+i*30));return q}
 function cusp(f,above){var ra=ramc+(above?f*90:180-f*90);for(var i=0;i<80;i++){var l=l4ra(ra)*Math.PI/180,dec=Math.asin(Math.sin(e)*Math.sin(l)),x=Math.max(-1,Math.min(1,Math.tan(phi)*Math.tan(dec))),ad=Math.asin(x)*180/Math.PI,r2=above?ramc+f*(90+ad):ramc+180-f*(90-ad);if(Math.abs(r2-ra)<1e-8)break;ra=r2}return l4ra(ra)}
 var c11=cusp(1/3,true),c12=cusp(2/3,true),c2=cusp(2/3,false),c3=cusp(1/3,false);
 return [asc,c2,c3,rev(mc+180),rev(c11+180),rev(c12+180),rev(asc+180),rev(c2+180),rev(c3+180),mc,c11,c12]}
function houseOfCusps(c,l){for(var i=0;i<12;i++){if(rev(l-c[i])<rev(c[(i+1)%12]-c[i]))return i+1}return 1}
function dm(t){var d=new Date(t);return d.getUTCDate()+' '+MON[d.getUTCMonth()]}
